import { test, expect } from "../helpers/theme-browser";
import { setThemePreferences, settleTheme } from "../helpers/theme-preferences";
import AxeBuilder from "@axe-core/playwright";
import type { Page } from "@playwright/test";

const nav = (page: Page) =>
  page.getByRole("navigation", { name: "Settings sections" });
const active = (page: Page) => nav(page).locator('[aria-current="location"]');
async function expectActive(page: Page, id: string) {
  await expect(active(page)).toHaveCount(1);
  await expect(active(page)).toHaveAttribute("href", `#${id}`);
}
async function scrollTo(page: Page, id: string, offset = 100) {
  await page.locator(`#${id}`).evaluate((el, offset) => {
    window.scrollTo({
      top: window.scrollY + el.getBoundingClientRect().top - offset,
      behavior: "instant",
    });
  }, offset);
}

test("settings rail: scrolling, shared row, anchors, history and keyboard", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto("/settings");
  await expect(page.locator("#danger")).toBeVisible();
  await expectActive(page, "outreach");
  const indicator = nav(page).locator("[data-settings-indicator]");
  await expect(indicator).toHaveAttribute("data-ready", "true");
  await expect(indicator).toHaveCSS("transition-duration", "0s");
  await scrollTo(page, "plan", 121);
  await expectActive(page, "outreach");
  await scrollTo(page, "plan", 119);
  await expectActive(page, "plan");
  await expect(page).toHaveURL(/\/settings$/);
  await scrollTo(page, "gmail");
  await expectActive(page, "gmail");
  const halfRow = await page.locator("#gmail").evaluate((el) => {
    return (
      (document.getElementById("remind")!.getBoundingClientRect().top -
        el.getBoundingClientRect().top) /
      2
    );
  });
  await scrollTo(page, "gmail", 121 - halfRow);
  await expectActive(page, "gmail");
  await scrollTo(page, "gmail", 119 - halfRow);
  await expectActive(page, "resume");
  await scrollTo(page, "remind", 119);
  await expectActive(page, "remind");
  await scrollTo(page, "remind", 121);
  await expectActive(page, "resume");
  await scrollTo(page, "gmail", 121 - halfRow);
  await expectActive(page, "gmail");
  await expect(page).toHaveURL(/\/settings$/);
  await nav(page)
    .getByRole("link", { name: "Attachment", exact: true })
    .click();
  await expectActive(page, "resume");
  await expect(page.locator("#resume-heading")).toBeFocused();
  await scrollTo(page, "gmail", 80);
  await expectActive(page, "resume");
  await scrollTo(page, "plan");
  await expectActive(page, "plan");
  await scrollTo(page, "gmail");
  await expectActive(page, "gmail");
  await expect(page).toHaveURL(/#resume$/);
  await expect(page.locator("#resume-heading")).toBeFocused();
  await page.evaluate(() =>
    window.scrollTo({
      top: document.documentElement.scrollHeight,
      behavior: "instant",
    }),
  );
  await expectActive(page, "danger");

  await page.goto("/settings#resume");
  await expectActive(page, "resume");
  await page.evaluate(() => {
    location.hash = "plan";
  });
  await expectActive(page, "plan");
  await page.goBack();
  await expectActive(page, "resume");
  await page.goForward();
  await expectActive(page, "plan");
  const gmail = nav(page).getByRole("link", { name: "Gmail", exact: true });
  await gmail.focus();
  await page.keyboard.press("Enter");
  await expect(page.locator("#gmail-heading")).toBeFocused();
  await expectActive(page, "gmail");
  // Modified clicks retain native navigation and never move heading focus.
  const modified = await gmail.evaluate((el) => {
    const event = new MouseEvent("click", {
      bubbles: true,
      cancelable: true,
      ctrlKey: true,
    });
    el.dispatchEvent(event);
    return event.defaultPrevented;
  });
  expect(modified).toBe(false);
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await nav(page).getByRole("link", { name: "Outreach roles" }).click();
  await expectActive(page, "outreach");
  await nav(page)
    .getByRole("link", { name: "Attachment", exact: true })
    .click();
  await expectActive(page, "resume");
  await expect
    .poll(() =>
      page
        .locator("#resume")
        .evaluate((el) => Math.round(el.getBoundingClientRect().top)),
    )
    .toBe(24);
  await expectActive(page, "resume");
});

test("settings rail: smooth navigation keeps the selected destination highlighted", async ({
  page,
  isMobile,
}) => {
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.setViewportSize({ width: 1280, height: 800 });
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto("/settings");
  await expect(page.locator("#danger")).toBeVisible();
  await expectActive(page, "outreach");
  const indicator = nav(page).locator("[data-settings-indicator]");
  await expect(indicator).toHaveAttribute("data-ready", "true");
  const initialPosition = await indicator.evaluate(
    (el) => getComputedStyle(el).transform,
  );
  await expect(indicator).toHaveCSS(
    "transition-duration",
    "0.28s, 0.28s, 0.28s, 0.28s",
  );
  await nav(page).evaluate((el) => {
    const changes: string[] = [];
    Object.assign(window, { settingsActiveChanges: changes });
    new MutationObserver(() => {
      changes.push(
        el.querySelector('[aria-current="location"]')?.getAttribute("href") ??
          "missing",
      );
    }).observe(el, {
      attributes: true,
      subtree: true,
      attributeFilter: ["aria-current"],
    });
  });
  await nav(page).getByRole("link", { name: "Danger zone" }).click();
  await expect(indicator).toHaveAttribute("data-danger", "true");
  await expect
    .poll(() => indicator.evaluate((el) => getComputedStyle(el).transform))
    .not.toBe(initialPosition);
  await expect
    .poll(() =>
      page.evaluate(() =>
        Math.abs(scrollY + innerHeight - document.documentElement.scrollHeight),
      ),
    )
    .toBeLessThanOrEqual(2);
  await expectActive(page, "danger");
  const changes = await page.evaluate(
    () =>
      (window as Window & { settingsActiveChanges?: string[] })
        .settingsActiveChanges,
  );
  expect(changes!.length).toBeGreaterThan(0);
  expect(changes!.filter((id) => id !== "#danger")).toEqual([]);
  await scrollTo(page, "plan");
  await expectActive(page, "plan");

  // A second click replaces an in-flight destination, including the shared row.
  await nav(page).getByRole("link", { name: "Danger zone" }).click();
  await nav(page)
    .getByRole("link", { name: "Attachment", exact: true })
    .dispatchEvent("click");
  await expect
    .poll(() =>
      page
        .locator("#resume")
        .evaluate((el) => Math.round(el.getBoundingClientRect().top)),
    )
    .toBe(24);
  await expectActive(page, "resume");

  // A destination near the bottom stays selected after reaching its position.
  const dataTop = await page
    .locator("#data")
    .evaluate((el) =>
      Math.min(
        scrollY + el.getBoundingClientRect().top - 24,
        document.documentElement.scrollHeight - innerHeight,
      ),
    );
  await nav(page).getByRole("link", { name: "Your data" }).click();
  await expect
    .poll(() => page.evaluate((top) => Math.abs(scrollY - top), dataTop))
    .toBeLessThanOrEqual(2);
  await expectActive(page, "data");
  // Interrupt on the first animation frame so automation latency cannot let
  // the browser reach Outreach before the interruption is delivered.
  await page.evaluate((isMobile) => {
    const start = scrollY;
    function interrupt() {
      if (scrollY >= start - 1) return;
      window.removeEventListener("scroll", interrupt);
      window.dispatchEvent(new Event(isMobile ? "touchstart" : "wheel"));
    }
    window.addEventListener("scroll", interrupt, { passive: true });
  }, isMobile);
  await nav(page).getByRole("link", { name: "Outreach roles" }).click();
  await expect(active(page)).not.toHaveAttribute("href", "#outreach");
  await scrollTo(page, "plan");
  await expectActive(page, "plan");
  expect(errors).toEqual([]);
});

test("settings rail: streamed targets and content resizing", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto("/settings");
  await expect(page.locator("#danger")).toBeVisible();
  // Recreate a Suspense boundary resolving after navigation is already mounted.
  await page.waitForFunction(() => {
    const link = document.querySelector(
      'nav[aria-label="Settings sections"] a',
    );
    return (
      link && Object.keys(link).some((key) => key.startsWith("__reactProps"))
    );
  });
  await page.evaluate(() => {
    const stack = document.getElementById("outreach")!.parentElement!;
    const content = document.createDocumentFragment();
    content.append(...stack.childNodes);
    location.hash = "resume";
    setTimeout(() => stack.append(content), 100);
  });
  await expectActive(page, "resume");
  await expect
    .poll(() =>
      page
        .locator("#resume")
        .evaluate((el) => Math.round(el.getBoundingClientRect().top)),
    )
    .toBe(24);
  await scrollTo(page, "gmail");
  // Disable native scroll anchoring to isolate observer-driven marker updates.
  await page.evaluate(() => {
    document.documentElement.style.overflowAnchor = "none";
  });
  await page.locator("#outreach").evaluate((el) => {
    el.style.minHeight = "1400px";
  });
  await expectActive(page, "outreach");
  await page.setViewportSize({ width: 768, height: 800 });
  await scrollTo(page, "resume");
  await expectActive(page, "resume");
  await scrollTo(page, "gmail");
  await expectActive(page, "gmail");
});

test("settings rail: four themes, responsive layout and accessibility", async ({
  page,
}, info) => {
  test.skip(info.project.name !== "desktop");
  test.setTimeout(180000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  for (const [appearance, theme] of [
    ["purple", "light"],
    ["purple", "dark"],
    ["vercel", "light"],
    ["vercel", "dark"],
  ]) {
    await setThemePreferences(page, appearance, theme);
    for (const width of [390, 768, 859, 860, 1280]) {
      await page.setViewportSize({ width, height: 900 });
      await page.goto("/settings");
      await expect(page.locator("#danger")).toBeVisible();
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
      await expect(
        nav(page).locator("[data-settings-indicator]"),
      ).toHaveAttribute("data-ready", "true");
      await settleTheme(page);
      await expectActive(page, "outreach");
      await expect(nav(page)).toHaveCSS(
        "position",
        width < 860 ? "relative" : "sticky",
      );
      await expect(nav(page)).toHaveCSS("gap", width < 860 ? "8px" : "4px");
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      for (const link of await nav(page).getByRole("link").all()) {
        const box = await link.boundingBox();
        expect(box!.height).toBeGreaterThanOrEqual(44);
        expect(
          await link.evaluate((el) => el.scrollWidth <= el.clientWidth),
        ).toBe(true);
        await expect(link.locator("svg")).toHaveAttribute("width", "16");
      }
      const marker = await nav(page)
        .locator("[data-settings-indicator]")
        .evaluate((el) => {
          const cs = getComputedStyle(el);
          return { width: cs.width, height: cs.height };
        });
      expect(width < 860 ? marker.height : marker.width).toBe("2px");
      await page.keyboard.press("Tab");
      await nav(page).getByRole("link", { name: "Outreach roles" }).focus();
      await expect(active(page)).toHaveCSS("outline-style", "solid");
      if ([390, 768, 1280].includes(width)) {
        await page.screenshot({
          path: info.outputPath(`${appearance}-${theme}-${width}.png`),
          fullPage: true,
        });
        const results = await new AxeBuilder({ page })
          .include('nav[aria-label="Settings sections"]')
          .analyze();
        expect(results.violations).toEqual([]);
      }
    }
  }
});
